cd /work && awk '/section_4_warnings:/ {
    if (/\[.*\]/) {
        gsub(/.*\[\s*/, "");
        gsub(/\s*\]/, "");
        lines = split($0, arr, ",");
        if (lines > 0) {
            for (i in arr) {
                gsub(/"/, "", arr[i]);
                gsub(/^ +/, "", arr[i]);
                print i ": " arr[i];
            }
        }
    } else {
        print "empty"
    }
}' .ai-project/registry/fleet-registry.yml

